// ── Langue des étiquettes ───────────────────────────────────────────────────────
// MapLibre n'a pas de map.setLanguage() (c'était une API du SDK MapTiler). On réécrit donc
// le text-field des couches de symboles : name:<lang> (puis name_en pour l'anglais) en
// priorité, avec l'expression d'origine du style en repli. L'expression d'origine est
// mémorisée par couche pour pouvoir changer de langue plusieurs fois sans l'empiler.
const originalTextFields = new WeakMap(); // map -> Map(layerId -> text-field d'origine)

// Convertit l'ancienne syntaxe "{name}" / "{name:latin} {name:nonlatin}" en expression.
const tokenStringToExpr = (str) => {
    const parts = [];
    let last = 0;
    str.replace(/\{([^}]+)\}/g, (m, key, idx) => {
        if (idx > last) parts.push(str.slice(last, idx));
        parts.push(["to-string", ["coalesce", ["get", key], ""]]);
        last = idx + m.length;
        return m;
    });
    if (last < str.length) parts.push(str.slice(last));
    return parts.length === 1 && typeof parts[0] !== "string" ? parts[0] : ["concat", ...parts];
};

const textFieldUsesName = (tf) => JSON.stringify(tf).includes("name");

const applyMapLanguage = (map, lang) => {
    const style = map.getStyle();
    if (!style?.layers) return;
    if (!originalTextFields.has(map)) originalTextFields.set(map, new Map());
    const originals = originalTextFields.get(map);
    const code = String(lang || "").toLowerCase();
    // "auto" / "latin" / vide : on garde le comportement par défaut du style.
    const useDefault = !code || code === "auto" || code === "latin" || code === "nonlatin";

    for (const layer of style.layers) {
        if (layer.type !== "symbol") continue;
        const current = map.getLayoutProperty(layer.id, "text-field");
        if (current === undefined) continue;
        if (!originals.has(layer.id)) {
            if (!textFieldUsesName(current)) continue; // étiquette sans nom (numéros de route...)
            originals.set(layer.id, current);
        }
        const original = originals.get(layer.id);
        if (useDefault) {
            map.setLayoutProperty(layer.id, "text-field", original);
            continue;
        }
        // Ancienne syntaxe "fonction" ({ stops: [...] }) : invalide dans un coalesce.
        if (original && typeof original === "object" && !Array.isArray(original)) continue;
        const fallback = typeof original === "string" ? tokenStringToExpr(original) : original;
        const candidates = [["get", `name:${code}`]];
        if (code === "en") candidates.push(["get", "name_en"]);
        map.setLayoutProperty(layer.id, "text-field", ["coalesce", ...candidates, fallback]);
    }
};

// Icône « i » (react-icons IoMdInformation) des tweets != MIL : rasterisée en image MapLibre.
