const INFO_ICON_ID = "tweet-info-icon";
const ensureInfoIcon = (map) => {
    if (map.hasImage(INFO_ICON_ID)) return;
    const size = 64; // px canvas ; pixelRatio 2 => 32 px à l'écran pour icon-size = 1
    let svg = renderToStaticMarkup(<IoMdInformation size={size} color={themeColor("white")} />);
    // react-icons ajoute déjà xmlns : le dupliquer rend le SVG invalide (image jamais chargée)
    if (!/xmlns=/.test(svg)) svg = svg.replace("<svg", '<svg xmlns="http://www.w3.org/2000/svg"');
    // currentColor n'a pas de contexte CSS dans une image : on force le blanc
    svg = svg.replace(/currentColor/g, themeColor("white"));
    const img = new Image(size, size);
    img.onerror = (e) => console.warn("[tweet-info-icon] SVG non chargé", e);
    img.onload = () => {
        if (map.hasImage(INFO_ICON_ID)) return;
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, size, size);
        try { map.addImage(INFO_ICON_ID, ctx.getImageData(0, 0, size, size), { pixelRatio: 2 }); } catch (e) { /* carte supprimée */ }
    };
    img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
};

