// Les images (addImage) sont stockées dans le style : elles sont perdues au setStyle.
// Cette fonction recrée les trames de hachures (idempotente).
const ensureHatchImages = (map) => {
    const makeHatch = (id, color, lineWidth, diagonal, size = 32) => {
        if (map.hasImage(id)) return;
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        ctx.strokeStyle = color;
        ctx.lineWidth = lineWidth;
        // 3 diagonales décalées pour que la trame se raccorde d'une tuile à l'autre
        for (const offset of [-size, 0, size]) {
            ctx.beginPath();
            if (diagonal === "/") { ctx.moveTo(offset, size); ctx.lineTo(offset + size, 0); }
            else { ctx.moveTo(offset, 0); ctx.lineTo(offset + size, size); }
            ctx.stroke();
        }
        map.addImage(id, ctx.getImageData(0, 0, size, size), { pixelRatio: 2 });
    };
    // Trame fine et aérée (tuile 40 px = période de 20 px à l'écran, trait 0,75 px) : elle
    // texture la zone sans masquer le fond de carte ; l'essentiel du rendu vient du halo + contour.
    makeHatch("hatch-restricted", themeColor("warning"), 1.5, "/", 40); // détroits RESTRICTED
    makeHatch("hatch-conflict-zones", themeColor("danger"), 1.5, "\\"); // zones de conflit
};

// ── Styles des zones de détroits (adaptés à la vue satellite) ───────────────────
// Les couches 'chokepoints-areas-*' sont fixes ; un style = un jeu de valeurs de peinture
// appliqué par applyChokepointAreaStyle (cf. init de la carte). Pour changer de style :
//   - par défaut : CHOKEPOINT_AREA_STYLE_DEFAULT
//   - sans recharger le code : ?cpstyle=neon dans l'URL, ou __setChokepointStyle('neon') en console
// Les valeurs « zoom » sont des paires [zoom, valeur, zoom, valeur, ...] (interpolation linéaire).
// Champs : closed / restricted = couleurs ; tint = voile uni (tintColor pour forcer une couleur) ;
// patterns = trame par statut (hatch | cross | lines | dots) ; glow / glowInner = halos flous ;
// casing = liseré sombre ; line = contour (dash = tirets, null = trait plein) ; accent = filet
// clair par-dessus le contour ; fade = part d'opacité conservée à z8 pour voile et trames ;
// thickness = coefficient global d'épaisseur (casing, line, accent).
const CHOKEPOINT_AREA_STYLES = {
    satellite: {
        closed: themeColor("danger"),
        restricted: themeColor("warning"),
        tintColor: null,
        tint: { closed: 0.35, restricted: 0.28 },
        fade: 0.6,
        thickness: 1.5, // coefficient d'épaisseur du contour (liseré + trait + filet) : 1 = valeurs ci-dessous, 1,5 = 50 % plus épais
        line: {
            width: [[3, 1.4], [8, 2.2]],
            opacity: 1,
            closedDash: null,
            restrictedDash: null,
        },
        accent: { width: [[3, 0.7], [8, 1.1]], opacity: 1 },
        casing: null,    // liseré sombre supprimé (ancien : width [[3, 3], [8, 4.2]], opacity 0.9)
        glow: null,      // halos supprimés (ancien : glow.width [[3, 16], [8, 28]], glowInner.width [[3, 6], [8, 11]])
        glowInner: null,
        patterns: {
            closed: { opacity: 0.45 },
            restricted: { opacity: 0.35 },
        },
        hover: 0.3,
    },
};
const CHOKEPOINT_AREA_STYLE_DEFAULT = 'satellite';
// Dessine une tuile de trame (idempotent). size en px canvas (pixelRatio 2 => moitié à l'écran).
// Pour "dots", lineWidth = rayon du point.
const drawChokepointPattern = (map, id, { kind, color, size = 32, lineWidth = 1.5, angle = "/" }) => {
    if (map.hasImage(id)) return;
    const canvas = document.createElement("canvas");
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext("2d");
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = lineWidth;
    const diagonals = (dir) => {
        // 3 diagonales décalées pour que la trame se raccorde d'une tuile à l'autre
        for (const o of [-size, 0, size]) {
            ctx.beginPath();
            if (dir === "/") { ctx.moveTo(o, size); ctx.lineTo(o + size, 0); }
            else { ctx.moveTo(o, 0); ctx.lineTo(o + size, size); }
            ctx.stroke();
        }
    };
    if (kind === "hatch") diagonals(angle);
    else if (kind === "cross") { diagonals("/"); diagonals("\\"); }
    else if (kind === "lines") {
        ctx.beginPath(); ctx.moveTo(0, size / 2); ctx.lineTo(size, size / 2); ctx.stroke();
    } else if (kind === "dots") {
        // quinconce : deux points par tuile
        for (const [x, y] of [[size / 4, size / 4], [(size * 3) / 4, (size * 3) / 4]]) {
            ctx.beginPath(); ctx.arc(x, y, lineWidth, 0, Math.PI * 2); ctx.fill();
        }
    }
    map.addImage(id, ctx.getImageData(0, 0, size, size), { pixelRatio: 2 });
};

// Crée les trames de tous les styles (perdues au setStyle, d'où la fonction idempotente).
const ensureChokepointPatterns = (map) => {
    if (!map.hasImage("cp-none")) map.addImage("cp-none", { width: 1, height: 1, data: new Uint8Array(4) });
    for (const [key, s] of Object.entries(CHOKEPOINT_AREA_STYLES)) {
        for (const status of ["closed", "restricted"]) {
            const pat = s.patterns?.[status];
            if (pat) drawChokepointPattern(map, `cp-${key}-${status}`, { ...pat, color: pat.color ?? s[status] });
        }
    }
};

